import { icon } from '../../core/icon.738be3be739c.mjs';
import { t } from '../../core/i18n.ec6fa659a9bf.mjs';

const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=(p,k=[])=>Array.isArray(p)?p:k.find(x=>Array.isArray(p?.[x]))?p[k.find(x=>Array.isArray(p?.[x]))]:[];
const activeStatuses=new Set(['planning','running','testing','recovering','ready']);
const doneStatuses=new Set(['completed','verified','pass','passed']);
function eventIcon(kind='') { const value=kind.toLowerCase(); if(value.includes('file')||value.includes('read')||value.includes('write'))return'file'; if(value.includes('command')||value.includes('shell')||value.includes('terminal'))return'terminal'; if(value.includes('tool')||value.includes('mcp'))return'tool'; if(value.includes('skill'))return'spark'; if(value.includes('agent')||value.includes('delegate'))return'activity'; if(value.includes('browser')||value.includes('web'))return'globe'; if(value.includes('verify')||value.includes('test'))return'check'; if(value.includes('permission')||value.includes('approval'))return'shield'; if(value.includes('error')||value.includes('fail'))return'warning'; if(value.includes('mission'))return'branch'; return'activity'; }
function eventTone(kind='',status=''){const text=`${kind} ${status}`.toLowerCase();if(/fail|error|blocked/.test(text))return'danger';if(/complete|pass|success|verified/.test(text))return'success';if(/permission|approval|waiting/.test(text))return'warning';return'active'}
function titleFor(event){if(event.type==='mission.planned')return event.payload?.summary??'Mission plan created';if(event.type==='security.route-gate')return `${event.payload?.method??''} ${event.payload?.route??'Runtime request'}`.trim();return event.title??event.message??event.summary??event.kind??event.type??'Agent event'}
function detailFor(event){if(event.type==='mission.planned')return `${event.payload?.taskCount??0} tasks · plan recorded`;if(event.type==='security.route-gate')return `${event.payload?.stage??'policy'} · ${event.payload?.outcome??'unknown'}`;return event.target??event.path??event.command??event.toolName??event.skillName??event.description??event.payload?.path??event.payload?.command??event.payload?.toolName??''}
function timestamp(event,language){const raw=event.createdAt??event.timestamp??event.time??event.seq; if(!raw)return''; const d=new Date(typeof raw==='number'&&raw<1e12?raw*1000:raw); return Number.isNaN(d.getTime())?String(raw):d.toLocaleString(language==='vi'?'vi-VN':'en-US',{hour:'2-digit',minute:'2-digit',month:'short',day:'numeric'})}
function missionIdFor(event){return event.missionId??event.refs?.missionId??event.payload?.missionId??null}
function humanEvent(event){return event.type!=='security.route-gate' && event.kind!=='security.route-gate'}
function taskProgress(tasks){if(!tasks.length)return 0;const done=tasks.filter(task=>doneStatuses.has(String(task.status).toLowerCase())).length;return Math.round(done/tasks.length*100)}

export function createActivityController({api,language='en',selectedMissionId=null,experience='workspace'}={}){
  let state={status:'loading',language,experience,events:[],missions:[],tasks:[],story:null,timeTravel:{checkpoints:[],selectedCheckpointId:null,comparison:null,action:null,error:null},error:null,filter:'all',follow:true,selectedMissionId:selectedMissionId||null,lastUpdatedAt:null};
  const snapshot=()=>structuredClone(state);
  async function compareCheckpoint(id=state.timeTravel.selectedCheckpointId){
    if(!id)return snapshot();state.timeTravel={...state.timeTravel,selectedCheckpointId:id,action:'comparing',error:null};
    try{const comparison=await api.get(`/api/time-travel/checkpoints/${encodeURIComponent(id)}/compare`);state.timeTravel={...state.timeTravel,comparison,action:null};}
    catch(error){state.timeTravel={...state.timeTravel,action:null,error:String(error?.message??error)}}return snapshot();
  }
  async function load({silent=false}={}){
    if(!silent)state.status='loading';
    const taskPath=state.selectedMissionId?`/api/tasks?missionId=${encodeURIComponent(state.selectedMissionId)}`:'/api/tasks';
    const storyPath=state.selectedMissionId?`/api/execution-story?missionId=${encodeURIComponent(state.selectedMissionId)}&level=${encodeURIComponent(state.experience)}&language=${encodeURIComponent(state.language)}&limit=2000`:null;
    const checkpointPath=state.selectedMissionId?`/api/time-travel/checkpoints?missionId=${encodeURIComponent(state.selectedMissionId)}`:null;
    const r=await Promise.allSettled([api.get('/api/events?limit=500'),api.get('/api/missions'),api.get(taskPath),api.get('/api/sovereign-kernel/snapshot'),storyPath?api.get(storyPath):Promise.resolve(null),checkpointPath?api.get(checkpointPath):Promise.resolve(null)]);
    const [events,missions,tasks,kernel,story,checkpointPayload]=r.map(x=>x.status==='fulfilled'?x.value:null);const kernelEvents=arr(kernel,['events','activity']);const checkpoints=arr(checkpointPayload,['checkpoints']);
    const previous=state.timeTravel??{};const selected=checkpoints.some(item=>item.id===previous.selectedCheckpointId)?previous.selectedCheckpointId:checkpoints[0]?.id??null;
    state={...state,status:'ready',events:[...arr(events,['events']),...kernelEvents].sort((a,b)=>Number(b.seq??Date.parse(b.createdAt??b.time??0))-Number(a.seq??Date.parse(a.createdAt??a.time??0))),missions:arr(missions,['missions']),tasks:arr(tasks,['tasks']),story:story?.schema==='nolane.execution-story.v1'?story:null,timeTravel:{...previous,checkpoints,selectedCheckpointId:selected,comparison:previous.comparison?.checkpointId===selected?previous.comparison:null},error:r.slice(0,4).every(x=>x.status==='rejected')?'Nolane runtime could not be reached.':null,lastUpdatedAt:new Date().toISOString()};
    if(selected&&!state.timeTravel.comparison&&!silent)await compareCheckpoint(selected);return snapshot();
  }
  async function createCheckpoint(label=null){if(!state.selectedMissionId)return snapshot();state.timeTravel={...state.timeTravel,action:'creating',error:null};try{const created=await api.post('/api/time-travel/checkpoints',{missionId:state.selectedMissionId,label:label??(language==='vi'?'Checkpoint thủ công':'Manual checkpoint')});await load({silent:true});state.timeTravel={...state.timeTravel,selectedCheckpointId:created.id,comparison:null,action:'created'};await compareCheckpoint(created.id);}catch(error){state.timeTravel={...state.timeTravel,action:null,error:String(error?.message??error)}}return snapshot();}
  async function createBranch(id=state.timeTravel.selectedCheckpointId){if(!id)return snapshot();state.timeTravel={...state.timeTravel,action:'branching',error:null};try{const result=await api.post(`/api/time-travel/checkpoints/${encodeURIComponent(id)}/branch`,{});state.timeTravel={...state.timeTravel,action:`branch:${result.worktree?.branch??'created'}`};}catch(error){state.timeTravel={...state.timeTravel,action:null,error:String(error?.message??error)}}return snapshot();}
  async function replayMission(id=state.timeTravel.selectedCheckpointId){if(!id)return snapshot();state.timeTravel={...state.timeTravel,action:'replaying',error:null};try{const result=await api.post(`/api/time-travel/checkpoints/${encodeURIComponent(id)}/replay`,{});state.timeTravel={...state.timeTravel,action:`replay:${result.mission?.id??'created'}`};}catch(error){state.timeTravel={...state.timeTravel,action:null,error:String(error?.message??error)}}return snapshot();}
  async function restoreFile(id,path,{confirmOverwrite=false}={}){if(!id||!path)return snapshot();state.timeTravel={...state.timeTravel,action:`restoring:${path}`,error:null};try{await api.post(`/api/time-travel/checkpoints/${encodeURIComponent(id)}/restore-file`,{path,confirmOverwrite});state.timeTravel={...state.timeTravel,action:`restored:${path}`,comparison:null};await compareCheckpoint(id);}catch(error){state.timeTravel={...state.timeTravel,action:null,error:String(error?.message??error)}}return snapshot();}
  return Object.freeze({snapshot,load,refresh:()=>load({silent:true}),setFilter(filter){state.filter=filter;return snapshot()},setFollow(follow){state.follow=Boolean(follow);return snapshot()},selectMission(id){state.selectedMissionId=id||null;state.timeTravel={checkpoints:[],selectedCheckpointId:null,comparison:null,action:null,error:null};return load({silent:true})},createCheckpoint,selectCheckpoint(id){state.timeTravel={...state.timeTravel,selectedCheckpointId:id,comparison:null};return compareCheckpoint(id)},compareCheckpoint,createBranch,replayMission,restoreFile});
}

function renderExecutionStory(state,lang){
  const story=state.story;if(!story)return'';const s=story.summary??{};
  const metrics=[[s.filesRead,lang==='vi'?'tệp đã đọc':'files read'],[s.filesChanged,lang==='vi'?'tệp đã đổi':'files changed'],[s.commands,lang==='vi'?'lệnh':'commands'],[s.tests,lang==='vi'?'kiểm thử':'checks'],[s.approvals,lang==='vi'?'phê duyệt':'approvals']].filter(([value])=>Number(value)>0);
  return `<section class="execution-story" aria-label="${lang==='vi'?'Câu chuyện thực thi':'Execution Story'}"><header><div><p class="eyebrow">${lang==='vi'?'Câu chuyện thực thi':'Execution Story'}</p><h2>${lang==='vi'?'Nolane đã làm gì':'What Nolane did'}</h2><p>${lang==='vi'?'Cùng một ledger, mức chi tiết phù hợp với tầng giao diện hiện tại.':'The same durable ledger, projected at the detail level of your current experience.'}</p></div><span data-tone="${s.failures?'danger':String(s.state).toLowerCase()==='completed'?'success':'active'}">${esc(s.currentPhase??s.state??'ready')}</span></header><div class="execution-story__metrics">${metrics.map(([value,label])=>`<span><strong>${Number(value)}</strong><small>${esc(label)}</small></span>`).join('')||`<span><strong>${Number(s.events??0)}</strong><small>${lang==='vi'?'sự kiện':'events'}</small></span>`}</div><div class="execution-story__phases">${(story.phases??[]).map((phase,index)=>`<article data-state="${esc(phase.state)}"><span>${index+1}</span><div><strong>${esc(phase.title)}</strong><p>${esc(phase.summary??'')}</p><small>${Number(phase.eventCount??0)} ${lang==='vi'?'sự kiện':'events'}${phase.metrics?.files?` · ${phase.metrics.files} ${lang==='vi'?'tệp':'files'}`:''}${phase.metrics?.tests?` · ${phase.metrics.tests} ${lang==='vi'?'kiểm thử':'checks'}`:''}</small></div>${phase.receiptSha256?`<details><summary>${lang==='vi'?'Receipt':'Receipt'}</summary><code>${esc(phase.receiptSha256)}</code></details>`:''}</article>`).join('')}</div>${story.receiptSha256?`<footer><span>${lang==='vi'?'Story receipt':'Story receipt'}</span><code>${esc(story.receiptSha256)}</code></footer>`:''}</section>`;
}

function renderTimeTravel(state,lang){
  if(!state.selectedMissionId)return'';const tt=state.timeTravel??{};const checkpoints=tt.checkpoints??[];const selected=checkpoints.find(item=>item.id===tt.selectedCheckpointId)??checkpoints[0]??null;const comparison=tt.comparison;const advanced=['studio','expert'].includes(state.experience);
  return `<section class="time-travel" aria-label="Time Travel"><header><div><p class="eyebrow">Time Travel</p><h2>${lang==='vi'?'Checkpoint và phục hồi an toàn':'Checkpoints and safe restoration'}</h2><p>${lang==='vi'?'Lịch sử cũ giữ nguyên; mọi phục hồi tạo receipt mới.':'History remains immutable; every restoration creates a new receipt.'}</p></div><button type="button" data-time-travel-action="create">${lang==='vi'?'Tạo checkpoint':'Create checkpoint'}</button></header>${tt.error?`<p class="time-travel__error" role="alert">${esc(tt.error)}</p>`:''}${tt.action?`<p class="time-travel__status" role="status">${esc(tt.action)}</p>`:''}${checkpoints.length?`<div class="time-travel__rail" role="listbox" aria-label="${lang==='vi'?'Các checkpoint':'Checkpoints'}">${checkpoints.map((checkpoint,index)=>`<button type="button" role="option" aria-selected="${checkpoint.id===selected?.id}" data-time-travel-action="select" data-time-travel-checkpoint="${esc(checkpoint.id)}"><span>${index+1}</span><strong>${esc(checkpoint.label)}</strong><small>${esc(checkpoint.createdAt)} · ${checkpoint.git?.dirty?(lang==='vi'?'có thay đổi':'dirty'):(lang==='vi'?'sạch':'clean')}${checkpoint.completeWorkingTreeCapture===false?` · ${lang==='vi'?'một phần':'partial'}`:''}</small></button>`).join('')}</div>`:`<div class="time-travel__empty"><strong>${lang==='vi'?'Chưa có checkpoint':'No checkpoints yet'}</strong><p>${lang==='vi'?'Tạo checkpoint để so sánh, mở nhánh hoặc khôi phục từng tệp.':'Create one to compare, branch, or restore individual files.'}</p></div>`}${selected?`<div class="time-travel__controls"><button type="button" data-time-travel-action="compare" data-time-travel-checkpoint="${esc(selected.id)}">${lang==='vi'?'So sánh hiện tại':'Compare current'}</button>${advanced?`<button type="button" data-time-travel-action="branch" data-time-travel-checkpoint="${esc(selected.id)}">${lang==='vi'?'Mở nhánh mới':'Create branch'}</button>`:''}<button type="button" data-time-travel-action="replay" data-time-travel-checkpoint="${esc(selected.id)}">${lang==='vi'?'Replay thành mission mới':'Replay as new mission'}</button><details><summary>${lang==='vi'?'Checkpoint receipt':'Checkpoint receipt'}</summary><code>${esc(selected.receiptSha256??'')}</code></details></div>`:''}${comparison?`<div class="time-travel__comparison"><header><strong>${lang==='vi'?'Khác biệt với hiện tại':'Difference from current'}</strong><span>${Number(comparison.summary?.changed??0)} ${lang==='vi'?'tệp':'files'}</span></header><div>${(comparison.changes??[]).slice(0,200).map(change=>`<article data-status="${esc(change.status)}"><span>${esc(change.status)}</span><code>${esc(change.path)}</code>${advanced?`<button type="button" data-time-travel-action="restore" data-time-travel-checkpoint="${esc(selected?.id)}" data-time-travel-path="${esc(change.path)}">${lang==='vi'?'Khôi phục tệp':'Restore file'}</button>`:''}</article>`).join('')||`<p>${lang==='vi'?'Trạng thái hiện tại khớp checkpoint.':'Current state matches the checkpoint.'}</p>`}</div><footer><code>${esc(comparison.receiptSha256??'')}</code></footer></div>`:''}</section>`;
}

function renderMissionSpotlight(state,lang){
  const mission=(state.missions??[]).find(item=>String(item.id)===String(state.selectedMissionId));
  if(!mission)return '';
  const tasks=(state.tasks??[]).filter(item=>String(item.missionId)===String(mission.id));const progress=taskProgress(tasks);
  return `<section class="mission-spotlight" aria-label="Selected mission"><header><div><p class="eyebrow">${lang==='vi'?'Nhiệm vụ đang chọn':'Selected mission'}</p><h2>${esc(mission.objective??mission.title??mission.id)}</h2><p>${esc(mission.metadata?.summary??(lang==='vi'?'Theo dõi kế hoạch, tác vụ và hoạt động trực tiếp.':'Track the plan, tasks, and live execution evidence.'))}</p></div><span class="mission-status" data-tone="${activeStatuses.has(mission.status)?'active':doneStatuses.has(mission.status)?'success':'neutral'}">${esc(mission.status??'draft')}</span></header><div class="mission-progress"><progress max="100" value="${progress}" aria-label="Mission progress ${progress}%"></progress><strong>${progress}%</strong><small>${tasks.filter(item=>doneStatuses.has(String(item.status).toLowerCase())).length}/${tasks.length} ${lang==='vi'?'tác vụ hoàn tất':'tasks complete'}</small></div><div class="mission-task-strip">${tasks.map(task=>`<article data-status="${esc(task.status)}"><span>${icon(task.role==='builder'?'tool':task.role==='reviewer'?'review':'search',{size:14})}</span><div><strong>${esc(task.title??task.id)}</strong><small>${esc(task.role??'agent')} · ${esc(task.status??'ready')}</small></div></article>`).join('')||`<p>${lang==='vi'?'Chưa có tác vụ.':'No tasks available.'}</p>`}</div><footer><a href="#/review/${encodeURIComponent(mission.id)}" data-route="/review/${encodeURIComponent(mission.id)}">${icon('review',{size:14})}${lang==='vi'?'Mở duyệt':'Open review'}</a><a href="#/workroom?mission=${encodeURIComponent(mission.id)}" data-route="/workroom?mission=${encodeURIComponent(mission.id)}">${icon('terminal',{size:14})}${lang==='vi'?'Mở Studio':'Open Studio'}</a><button type="button" data-activity-mission="">${lang==='vi'?'Xem mọi hoạt động':'View all activity'}</button></footer></section>`;
}

export function renderActivityView(state={}){
  const lang=state.language??'en';
  const scoped=(state.events??[]).filter(event=>!state.selectedMissionId||String(missionIdFor(event))===String(state.selectedMissionId));
  const filtered=scoped.filter(event=>state.filter==='system'?event.type==='security.route-gate':state.filter==='all'?humanEvent(event):String(event.kind??event.type??'').toLowerCase().includes(state.filter));
  const running=(state.missions??[]).filter(m=>activeStatuses.has(String(m.status).toLowerCase())).length;const pending=(state.tasks??[]).filter(m=>['needs_input','awaiting_approval','permission_required'].includes(m.status)).length;
  return `<section class="surface-page activity-page"><header class="surface-page__header"><div><p class="eyebrow">${t('activity.live',lang)} · Execution observability</p><h1>${t('activity.title',lang)}</h1><p>${t('activity.subtitle',lang)}</p></div><div class="surface-stat-row"><span><strong>${running}</strong><small>${lang==='vi'?'đang chạy':'running'}</small></span><span><strong>${pending}</strong><small>${lang==='vi'?'cần xử lý':'needs you'}</small></span><span><strong>${scoped.length}</strong><small>${lang==='vi'?'sự kiện':'events'}</small></span></div></header>${renderMissionSpotlight(state,lang)}${renderExecutionStory(state,lang)}${renderTimeTravel(state,lang)}<div class="activity-toolbar"><div class="segmented-control" role="group" aria-label="Activity filters">${[['all',lang==='vi'?'Hoạt động AI':'Agent activity'],['file',lang==='vi'?'Tệp':'Files'],['command',lang==='vi'?'Lệnh':'Commands'],['tool',lang==='vi'?'Công cụ':'Tools'],['test',lang==='vi'?'Kiểm thử':'Tests'],['system',lang==='vi'?'Hệ thống':'System']].map(([id,label])=>`<button type="button" data-activity-filter="${id}" aria-pressed="${state.filter===id}">${label}</button>`).join('')}</div><label class="follow-toggle"><input type="checkbox" data-activity-follow${state.follow?' checked':''}><span>${lang==='vi'?'Theo dõi trực tiếp':'Follow live'}</span></label></div>${state.status==='loading'?`<div class="page-loading"><span class="spinner"></span>${t('common.loading',lang)}</div>`:state.error?`<div class="page-error">${icon('warning',{size:18})}<span>${esc(state.error)}</span></div>`:filtered.length?`<div class="activity-filament" data-follow="${state.follow}">${filtered.map((e,i)=>{const kind=e.kind??e.type??'event';const tone=eventTone(kind,e.status);return `<article class="activity-event" data-tone="${tone}" data-event-index="${i}"><div class="activity-event__node">${icon(eventIcon(kind),{size:16})}</div><div class="activity-event__body"><header><span class="activity-event__kind">${esc(String(kind).replaceAll('_',' '))}</span><time>${esc(timestamp(e,lang))}</time></header><strong>${esc(titleFor(e))}</strong>${detailFor(e)?`<code>${esc(detailFor(e))}</code>`:''}${e.receiptSha256||e.payload?.receiptSha256?`<details><summary>${lang==='vi'?'Bằng chứng':'Evidence receipt'}</summary><code>${esc(e.receiptSha256??e.payload.receiptSha256)}</code></details>`:''}</div></article>`}).join('')}</div>`:`<div class="empty-state page-empty"><span>${icon('activity',{size:20})}</span><strong>${lang==='vi'?'Chưa có hoạt động phù hợp':'No matching activity yet'}</strong><p>${state.filter==='system'?(lang==='vi'?'Các sự kiện hệ thống sẽ xuất hiện khi runtime xử lý yêu cầu.':'Runtime policy and route events will appear here.'):t('activity.empty',lang)}</p></div>`}</section>`;
}
